package dev.hrutvik.billing.outbox;
import org.apache.kafka.clients.producer.ProducerRecord; import org.junit.jupiter.api.Test; import org.mockito.ArgumentCaptor; import org.springframework.kafka.core.KafkaTemplate; import java.time.*; import java.util.*; import java.util.concurrent.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class OutboxRelayTest {
 @Test void publishesWithStableKeyAndHeadersThenCompletesLease() throws Exception {var leases=mock(OutboxLeaseService.class);var kafka=mock(KafkaTemplate.class);var event=new OutboxEvent(UUID.randomUUID(),UUID.randomUUID(),"USAGE_RECORDED","tenant-a","{\"quantity\":2}",Instant.now());when(leases.claim(any(),eq(10),any())).thenReturn(List.of(event));when(kafka.send(any(ProducerRecord.class))).thenReturn(CompletableFuture.completedFuture(null));var relay=new OutboxRelay(leases,kafka,10,Duration.ofSeconds(30),Duration.ofSeconds(1),"usage-topic");relay.publishBatch();var record=ArgumentCaptor.forClass(ProducerRecord.class);verify(kafka).send(record.capture());assertThat(record.getValue().topic()).isEqualTo("usage-topic");assertThat(record.getValue().key()).startsWith("tenant-a:");assertThat(record.getValue().headers().lastHeader("event-id")).isNotNull();verify(leases).markPublished(event.getId());verify(leases,never()).release(any());}
 @Test void brokerFailureReleasesLeaseForRetry(){var leases=mock(OutboxLeaseService.class);var kafka=mock(KafkaTemplate.class);var event=new OutboxEvent(UUID.randomUUID(),UUID.randomUUID(),"USAGE_RECORDED","tenant-a","{}",Instant.now());var failed=new CompletableFuture();failed.completeExceptionally(new RuntimeException("broker unavailable"));when(kafka.send(any(ProducerRecord.class))).thenReturn(failed);var relay=new OutboxRelay(leases,kafka,10,Duration.ofSeconds(30),Duration.ofMillis(50),"usage-topic");relay.publish(event);verify(leases).release(event.getId());verify(leases,never()).markPublished(any());}
}
